                key=(sc,nfill)
                if best is None or key<best[0]: best=(key,(sidx,tidx,dy,dx))
    _,(sidx,tidx,dy,dx)=best
    ref=tgt=bands[sidx if sidx==0 else 1]
    out=[r[:] for r in g]
    for a in bands[tidx]:
        for c in range(W):
            if g[a][c]==bgv and 0<=a-dy<H and 0<=c-dx<W and g[a-dy][c-dx]!=bgv:
